  ('a495cf87-6c51-43d1-b2be-8e1783e34c4f', 'f6a7b8c9-0d1e-4f12-9a12-2b3c4d5e6f32', 'bccfb4bd-8483-4bc7-8971-08e0b58202d1', 'concept'::public.curated_course_node_type, 'crowd, protest, and emergency coverage safety', null, 2),
