update public.learning_paths
set
  title = 'Digital and Social Media Journalism',
  goal = 'Digital and Social Media Journalism',
  summary = 'A newsroom-style course in digital and social media journalism. Students learn to write for the web, optimize accurate journalism for discovery, report and verify social content, engage communities, interpret analytics, produce live coverage, build newsletters and podcasts, handle user-generated content, counter misinformation, use digital storytelling tools, and evaluate algorithmic and AI-mediated publishing environments. The course emphasizes verification, public service, accessibility, audience trust, ethical distribution, and publishable portfolio work.',
  data = $dsmjjson${"slug": "digital-and-social-media-journalism", "title": "Digital and Social Media Journalism", "description": "A newsroom-style course in digital and social media journalism. Students learn to write for the web, optimize accurate journalism for discovery, report and verify social content, engage communities, interpret analytics, produce live coverage, build newsletters and podcasts, handle user-generated content, counter misinformation, use digital storytelling tools, and evaluate algorithmic and AI-mediated publishing environments. The course emphasizes verification, public service, accessibility, audience trust, ethical distribution, and publishable portfolio work.", "topics": [{"id": "7ea10826-4597-4faf-8057-84271ce24163", "type": "topic", "title": "Writing for the Web", "description": "Digital journalism rewards clarity, structure, speed, and reader usefulness. This unit teaches students to write stories that work on screens, in feeds, and across multiple entry points without losing reporting depth.", "children": [{"id": "9360176b-c95f-41e7-891d-bc7405a014e9", "type": "subtopic", "title": "Digital story architecture", "children": [{"id": "7afb9f9a-0c92-410e-a75f-d30c3e3342e9", "type": "concept", "title": "headlines, decks, nut grafs, and summary boxes"}, {"id": "5729e3a0-684e-48a0-abe8-715b52622ca7", "type": "concept", "title": "chunking, subheads, and scannable sections"}, {"id": "ee6bf283-b9a3-4681-a071-039fce6d2e45", "type": "concept", "title": "links, context modules, and related-story paths"}], "description": "Students learn how online stories are scanned, entered, shared, and updated, then structure work for fast comprehension and sustained reading."}, {"id": "f774335b-5d01-480e-b6e6-ca0d66eafbc9", "type": "subtopic", "title": "Web voice and precision", "children": [{"id": "d524349b-1ed7-4198-9383-254a6a2be645", "type": "concept", "title": "plain-language reporting"}, {"id": "d355be1c-c580-4efc-990f-5ca3a16367c3", "type": "concept", "title": "active verbs and short paragraphs"}, {"id": "630f7e26-7ddf-417d-8668-68f1885c4374", "type": "concept", "title": "explainers, service journalism, and FAQ formats"}], "description": "Students practice concise, conversational, accurate language suited to mobile readers and platform distribution."}, {"id": "aa4b07b3-8d8e-4ab0-84fc-a6af32ae5d67", "type": "subtopic", "title": "Publishing workflows", "children": [{"id": "2ab43b49-1469-4df3-b091-67be4ae1b923", "type": "concept", "title": "CMS fields and story templates"}, {"id": "5151d205-75f5-406b-a26a-b1b57a2753b4", "type": "concept", "title": "tags, categories, slugs, and embeds"}, {"id": "bb43f62a-65f1-49b6-9c49-682a13e28b45", "type": "concept", "title": "versioning, corrections, and update notes"}], "description": "Students understand how stories move through a content management system and how metadata affects presentation and discovery."}]}, {"id": "49c08b04-49fe-44a3-84f0-39e01b6d0311", "type": "topic", "title": "Search Engine Optimization", "description": "SEO is treated as public-service discoverability rather than gimmickry. Students learn to make accurate journalism findable while preserving editorial independence and human-centered writing.", "children": [{"id": "c1d1bd91-3c41-4d9d-af3b-c89d5bf38cf4", "type": "subtopic", "title": "Search intent and keyword judgment", "children": [{"id": "843c930e-0113-4752-94a3-49a80af3bc10", "type": "concept", "title": "search intent types"}, {"id": "805eb53e-cae4-45a3-ac7b-41cf93362eab", "type": "concept", "title": "keyword research basics"}, {"id": "93175722-be0e-4413-a8fb-0abb21963df5", "type": "concept", "title": "evergreen versus breaking-news search"}], "description": "Students learn to identify what audiences are asking and how to answer those questions without flattening nuance."}, {"id": "c0bb240e-1f0f-4817-9d73-3d705ed4a027", "type": "subtopic", "title": "Headlines, metadata, and structured context", "children": [{"id": "fd44d8e3-2a50-4242-968d-c7e9569a7b5f", "type": "concept", "title": "SEO headlines and social headlines"}, {"id": "2e2977ee-8c76-46fa-b960-c1b5b4fe4527", "type": "concept", "title": "meta descriptions and URL slugs"}, {"id": "32eb0999-12ad-4dba-9bf5-ad1a4d1419d8", "type": "concept", "title": "schema, alt text, and internal links"}], "description": "The course connects SEO mechanics to editorial decisions about framing, clarity, and accuracy."}, {"id": "a604909c-ea16-44d9-ad61-1c337dd27fec", "type": "subtopic", "title": "Search accountability", "children": [{"id": "ea2f7577-9cb7-4c3f-9dbe-17dcce835e66", "type": "concept", "title": "clickbait avoidance"}, {"id": "e4f43bea-15af-4165-8a3c-643c08223f20", "type": "concept", "title": "sensitive-term handling"}, {"id": "61264f6a-2a0b-4114-950f-b1eba8f89f27", "type": "concept", "title": "balancing relevance with dignity"}], "description": "Students evaluate SEO choices ethically, especially when topics involve harm, identity, crisis, or public health."}]}, {"id": "2c3c39c6-3036-44fb-8e34-79471d4db8f7", "type": "topic", "title": "Social Media Reporting and Verification", "description": "Social platforms are reporting environments, distribution channels, and misinformation vectors. This unit trains students to find leads, verify claims, and report responsibly in fast-moving public networks.", "children": [{"id": "9ac72fad-520e-4e7f-926b-4e5a807cf3f0", "type": "subtopic", "title": "Platform-aware reporting", "children": [{"id": "9d4a0e3d-df88-4a90-b8fd-bb0aa327a9d6", "type": "concept", "title": "X/Twitter, TikTok, Instagram, Reddit, Facebook, LinkedIn, and emerging platforms"}, {"id": "c0aaa106-c7e8-4d38-90be-7bfe1f138b58", "type": "concept", "title": "public posts versus private groups"}, {"id": "f7b91f8b-5043-4883-b255-c0d59d57b6ad", "type": "concept", "title": "platform norms and source expectations"}], "description": "Students learn how different platforms shape sourcing, visibility, tone, and evidence."}, {"id": "b184fbea-1288-4c85-ab49-404a67b00bf0", "type": "subtopic", "title": "Verification of social content", "children": [{"id": "e03f556f-4cec-46a5-bf74-a966e5bb5a1e", "type": "concept", "title": "source triangulation"}, {"id": "259c7c6e-a172-4608-90ed-770856b34602", "type": "concept", "title": "reverse image and video search"}, {"id": "e25990a5-739b-4da8-8807-a32c3ba3f1f4", "type": "concept", "title": "geolocation, chronolocation, and metadata limits"}], "description": "Students practice a repeatable workflow for checking posts, profiles, images, video, timestamps, and geolocation before publication."}, {"id": "8a22bcae-feb0-4fa0-95aa-f7efca00d8df", "type": "subtopic", "title": "Ethical sourcing online", "children": [{"id": "6bd80274-d394-4b02-8ba1-cfcd45bdffb0", "type": "concept", "title": "direct-message reporting"}, {"id": "3b84266d-2d15-47cd-8c49-428881dc291c", "type": "concept", "title": "embedding and screenshot ethics"}, {"id": "2ee81d85-1a19-413b-8407-c6bc805ba477", "type": "concept", "title": "protecting vulnerable sources"}], "description": "Students examine consent, privacy, trauma, and harassment risks when using material from digital communities."}]}, {"id": "96e34e94-e93e-4803-80a8-932144b9d973", "type": "topic", "title": "Audience Engagement", "description": "Engagement is more than promotion. Students learn how journalists listen to communities, invite participation, build trust, and turn audience needs into stronger reporting.", "children": [{"id": "691e8fdb-5ccc-4e45-8635-d0b913848fab", "type": "subtopic", "title": "Community listening", "children": [{"id": "7565096f-08da-4710-951a-a66ea33f3f96", "type": "concept", "title": "callouts and question forms"}, {"id": "cc8b14cf-971f-4f24-86fa-68e51087bfb1", "type": "concept", "title": "listening posts and community groups"}, {"id": "b45357bb-adf7-466b-8304-cd7a91f0c1a7", "type": "concept", "title": "audience personas and information needs"}], "description": "Students practice identifying audience questions, information needs, and underserved publics before and during reporting."}, {"id": "d8d1fd20-ba16-46a8-91e1-148a30c048d3", "type": "subtopic", "title": "Engagement formats", "children": [{"id": "b9163547-e46a-40b8-873b-2c531e6bb183", "type": "concept", "title": "Q&As, AMAs, explainers, and live chats"}, {"id": "eed48b60-d193-4221-b21f-361d74e29d86", "type": "concept", "title": "crowdsourcing tips and documents"}, {"id": "623ec85b-ad17-4847-a633-61390b70af7a", "type": "concept", "title": "moderation and comment strategy"}], "description": "Students design interaction points that improve reporting and public usefulness rather than chasing vanity interaction."}, {"id": "97c9ece5-bfe2-4d2c-8ec1-01e943d6fdec", "type": "subtopic", "title": "Trust and transparency", "children": [{"id": "506696f3-1dfd-4645-892f-c623062bf6e1", "type": "concept", "title": "behind-the-story notes"}, {"id": "6b664493-a02e-4032-b082-9c7ae1b75024", "type": "concept", "title": "source transparency"}, {"id": "6664ae82-8220-4b77-bc76-392c30a113fe", "type": "concept", "title": "accountability loops"}], "description": "Students learn to explain reporting methods, uncertainty, corrections, and editorial choices in ways audiences can evaluate."}]}, {"id": "85c55b49-d28d-491f-81fe-1f1e7eda2330", "type": "topic", "title": "Analytics and Metrics", "description": "Analytics help journalists understand reach, loyalty, behavior, and service. This unit teaches students to interpret metrics without letting dashboards replace editorial judgment.", "children": [{"id": "bcdcb5ee-8fa8-41c5-8451-41062dd0c9ed", "type": "subtopic", "title": "Metric literacy", "children": [{"id": "1be9aa14-1a91-4075-b7cc-f4082e2092ab", "type": "concept", "title": "pageviews, uniques, engaged time, recirculation, and loyalty"}, {"id": "68a532bd-cab3-4d20-b754-604b393b7f49", "type": "concept", "title": "newsletter open and click rates"}, {"id": "4759b2cf-dd0d-46fb-afc3-827852085df3", "type": "concept", "title": "conversion, retention, and membership signals"}], "description": "Students distinguish useful signals from misleading numbers and connect metrics to editorial goals."}, {"id": "2232482f-75d2-46ca-a16f-d72ab85d27fe", "type": "subtopic", "title": "Audience insight for editorial decisions", "children": [{"id": "585a2e02-9130-42a9-9a59-f449089809e4", "type": "concept", "title": "headline and format tests"}, {"id": "9f7b37a6-2c2a-4a01-8081-34b37e033f6e", "type": "concept", "title": "traffic-source analysis"}, {"id": "a3aae4aa-df9d-4da0-99da-d97ba9952bce", "type": "concept", "title": "topic gaps and service opportunities"}], "description": "Students use analytics to refine story formats, timing, distribution, and follow-up coverage."}, {"id": "c397558b-a285-4146-b5d1-a36cc22fcf96", "type": "subtopic", "title": "Ethics of measurement", "children": [{"id": "4892ff80-848d-4c53-9d7a-65d2d02423ea", "type": "concept", "title": "attention incentives"}, {"id": "b0e9456a-c849-45bd-838e-1ddf6d14722e", "type": "concept", "title": "privacy and consent"}, {"id": "e8cf9935-5ad5-40ef-93cb-1cf31e9bb369", "type": "concept", "title": "equity in audience measurement"}], "description": "Students critique how metrics can distort newsroom priorities or exclude communities."}]}, {"id": "a7327c83-d184-467d-a8a2-30c7aa7f0cec", "type": "topic", "title": "Live Blogging and Real-Time Reporting", "description": "Real-time journalism requires speed with discipline. Students learn to publish accurate updates during unfolding events while signaling uncertainty and maintaining a clear record.", "children": [{"id": "db95bab9-86d4-4137-8b00-b5da1fb0fdc8", "type": "subtopic", "title": "Live coverage planning", "children": [{"id": "dad26377-1a83-4e73-bfde-f9131e499ec0", "type": "concept", "title": "roles and handoffs"}, {"id": "961cf788-05be-4702-b7af-b0ef96f92d45", "type": "concept", "title": "source lists and verification checkpoints"}, {"id": "9bd48279-ad5d-49c5-854f-1108a38da060", "type": "concept", "title": "prewritten context and explainers"}], "description": "Students prepare workflows for elections, trials, storms, sports, protests, public meetings, and breaking-news events."}, {"id": "d6eaaed1-c463-455b-8d5e-4080b4e43bfc", "type": "subtopic", "title": "Writing live updates", "children": [{"id": "cdcc908a-d239-40f4-be2c-5f2d852f11a2", "type": "concept", "title": "time-stamped entries"}, {"id": "15e8de81-e785-437d-91b6-4fc6d5b657f2", "type": "concept", "title": "context paragraphs"}, {"id": "7a5456fe-4244-412a-98fa-c81a7977ef9d", "type": "concept", "title": "corrections and update labels"}], "description": "Students practice concise update writing that tells readers what changed, what is known, and what remains uncertain."}, {"id": "bccfb4bd-8483-4bc7-8971-08e0b58202d1", "type": "subtopic", "title": "Safety and harm reduction", "children": [{"id": "6b842ad5-1d3d-4411-a160-fd0fb2f738df", "type": "concept", "title": "rumor control"}, {"id": "8ca4ec60-82a2-4e86-8735-f7fc222b8b35", "type": "concept", "title": "image and video warnings"}, {"id": "a495cf87-6c51-43d1-b2be-8e1783e34c4f", "type": "concept", "title": "crowd, protest, and emergency coverage safety"}], "description": "Students learn to reduce amplification of rumors, graphic content, identifying details, and operationally sensitive information."}]}, {"id": "ae823cf4-e4b5-4e5a-871e-a846709bd16e", "type": "topic", "title": "Newsletters and Podcasts", "description": "Owned channels help newsrooms build habit, voice, loyalty, and direct audience relationships. Students learn to design editorial products that serve readers and listeners consistently.", "children": [{"id": "d6b5249c-529d-475e-b4e1-ab1fa26a081d", "type": "subtopic", "title": "Newsletter strategy", "children": [{"id": "3b0d83da-3fd2-49f6-9a81-3a43bec8055f", "type": "concept", "title": "curation versus original reporting"}, {"id": "5caeb368-c588-4e4f-aeb9-ece9d26e1e17", "type": "concept", "title": "subject lines and preview text"}, {"id": "2e567479-05ed-4b07-9df2-f676d213a4c9", "type": "concept", "title": "segmentation, cadence, and habit"}], "description": "Students develop newsletters around audience need, editorial promise, rhythm, and measurable value."}, {"id": "264ce598-bce1-471f-bed9-cc2692a8d09c", "type": "subtopic", "title": "Podcast and audio journalism basics", "children": [{"id": "60609a94-a41e-4afb-9e49-676d791104eb", "type": "concept", "title": "show premise and episode structure"}, {"id": "70e8cd76-369b-44f6-81c7-4ec37bb7d996", "type": "concept", "title": "script writing for the ear"}, {"id": "1b87b961-0d1b-4ba6-a187-efe617859ff8", "type": "concept", "title": "recording, editing, and host-read accountability"}], "description": "Students learn the editorial and production foundations of short news audio and conversational formats."}, {"id": "745581dd-30fb-4e20-97dc-bc794820012d", "type": "subtopic", "title": "Distribution and relationship-building", "children": [{"id": "f3acc738-8953-49e9-a3bf-0ba94c1498bd", "type": "concept", "title": "calls to action"}, {"id": "07e2ce89-ff72-48fb-a00e-0ea5480592f3", "type": "concept", "title": "listener and reader questions"}, {"id": "5c8abb5a-ec74-4bc1-9054-7ac8beddfcae", "type": "concept", "title": "cross-platform promotion"}], "description": "Students connect newsletters and podcasts to community, membership, social promotion, and feedback loops."}]}, {"id": "fd4af579-1b31-4d15-93df-4058ff4d07af", "type": "topic", "title": "User-Generated Content", "description": "UGC can be eyewitness evidence, community knowledge, or misleading material. This section teaches students to use audience-contributed content with consent, context, verification, and care.", "children": [{"id": "792b13e2-a6b9-4b0a-aea4-19352547d5b4", "type": "subtopic", "title": "Finding and evaluating UGC", "children": [{"id": "9ec914c6-02c9-4fa3-a55f-2f560c7ae205", "type": "concept", "title": "eyewitness video and photos"}, {"id": "66546820-abb7-4645-9012-ad9512d1b420", "type": "concept", "title": "public records from communities"}, {"id": "66a4640b-c826-40bc-9d4b-603bedb44f61", "type": "concept", "title": "source identity and motive checks"}], "description": "Students learn to identify useful public material and assess whether it is authentic, newsworthy, and ethical to use."}, {"id": "5049f074-c7e1-44c6-b0f5-3283a600211a", "type": "subtopic", "title": "Permissions and attribution", "children": [{"id": "c3675383-d44e-4b28-b6cd-1f4b7b957124", "type": "concept", "title": "license and reuse questions"}, {"id": "6106ab09-a88d-4489-8a6e-2582ef8772d3", "type": "concept", "title": "credit language"}, {"id": "0b09ffbc-3835-4691-88e4-600c043f3b4c", "type": "concept", "title": "archiving permission records"}], "description": "Students practice asking for permission, crediting contributors, and documenting rights decisions."}, {"id": "9ba5056c-98cd-4905-95d0-534f4b88e9be", "type": "subtopic", "title": "Context and representation", "children": [{"id": "dd7b3c18-8031-4b24-b604-dac2fcc5b573", "type": "concept", "title": "community norms"}, {"id": "61d5b599-c4e5-4506-8035-b164efb21f77", "type": "concept", "title": "identity and safety concerns"}, {"id": "d0e1dcf6-c602-4c80-a637-dd4b47e22e6a", "type": "concept", "title": "avoiding spectacle and extraction"}], "description": "Students learn to avoid stripping posts from their social, cultural, or emotional context."}]}, {"id": "d9b349ac-ae00-4c86-8306-0326e5e76a32", "type": "topic", "title": "Misinformation and Fact-Checking", "description": "Digital journalists need a strong defense against falsehoods, manipulation, and information disorder. Students learn verification methods, debunking strategy, and careful language for uncertainty.", "children": [{"id": "6fe34c72-3cfb-4585-9449-56928c1970b0", "type": "subtopic", "title": "Information disorder frameworks", "children": [{"id": "ca2f9940-a1df-477c-add0-0a1a7fb6f97b", "type": "concept", "title": "motives and spread patterns"}, {"id": "80b0948f-9764-4bc6-818f-3814ddab4c3d", "type": "concept", "title": "misleading context and manipulated media"}, {"id": "16c5a5a7-fed0-4cf4-af61-4592048f2c9c", "type": "concept", "title": "networked amplification"}], "description": "Students distinguish misinformation, disinformation, malinformation, satire, propaganda, scams, and coordinated manipulation."}, {"id": "37c3b604-9df4-49e3-b1d2-c9b95e3ac299", "type": "subtopic", "title": "Fact-checking workflow", "children": [{"id": "a4ea36aa-535d-4222-ac20-ad1355cde24e", "type": "concept", "title": "claim-review criteria"}, {"id": "2e170183-77b5-4353-8c1d-7212be0b7daa", "type": "concept", "title": "primary sources and expert evidence"}, {"id": "e9485dea-76ba-4e8e-aece-51d38ace8f40", "type": "concept", "title": "correction and update practices"}], "description": "Students practice claim selection, evidence gathering, expert consultation, and transparent rating or explanation."}, {"id": "fb91c29f-b7c3-4333-af03-2156858b48ca", "type": "subtopic", "title": "Debunking without amplification", "children": [{"id": "73bd4a47-f328-47b5-a8e7-1cbaa3f9b229", "type": "concept", "title": "truth sandwich techniques"}, {"id": "f08826f4-4f54-460b-bcdb-b15b6aefef27", "type": "concept", "title": "prebunking and media literacy"}, {"id": "1f80934b-4430-4a5c-94c0-b2689b9df78e", "type": "concept", "title": "visual debunks and share cards"}], "description": "Students learn to write corrections and explainers that reduce harm instead of spreading the false claim further."}]}, {"id": "cd20d642-0bb6-4f20-93e3-304b4e2ca64c", "type": "topic", "title": "Digital Storytelling Tools", "description": "Digital storytelling should fit the story, not decorate it. Students learn to choose and produce formats that make evidence clearer, scenes richer, and audience use easier.", "children": [{"id": "262cd123-2234-4c9e-8ef1-47530ab02700", "type": "subtopic", "title": "Tool selection and story fit", "children": [{"id": "e8390a45-19f4-49e3-9ff2-905eb0383169", "type": "concept", "title": "format audits"}, {"id": "969dfd9e-56a6-4e8c-ab97-65325ed0a9e0", "type": "concept", "title": "minimum viable multimedia"}, {"id": "62a12c0c-87e6-4d73-929d-7d1c34f83c70", "type": "concept", "title": "storyboarding and asset planning"}], "description": "Students decide when a story needs text, video, audio, maps, timelines, interactives, databases, or social-first packages."}, {"id": "52706032-6e81-4a03-91bb-91a6811e3e96", "type": "subtopic", "title": "Production with accessible design", "children": [{"id": "b2ab30a4-18ed-480f-8ba5-2a7adc025238", "type": "concept", "title": "captions and transcripts"}, {"id": "812385dd-e10f-41f6-8dd9-5c95ed301d04", "type": "concept", "title": "alt text and color contrast"}, {"id": "5879ef69-ecfa-4474-859a-ed795e1ac84e", "type": "concept", "title": "mobile-first layout and load performance"}], "description": "Students build digital packages that are legible, inclusive, and usable across devices."}, {"id": "c32d6efc-8d52-45c0-a888-e45dcbcf2f2f", "type": "subtopic", "title": "Portfolio-quality publishing", "children": [{"id": "91357299-8b06-46c3-97c6-69407bba5ff6", "type": "concept", "title": "asset rights and credits"}, {"id": "6dbe9a7e-e358-4262-b4cf-5cc39c5bc3af", "type": "concept", "title": "quality assurance checklist"}, {"id": "292259ea-d7a5-47af-8b81-1df827df68e8", "type": "concept", "title": "post-publication updates"}], "description": "Students produce a final package with reporting, metadata, visuals, distribution, and a reflective production memo."}]}, {"id": "38bf62aa-a9c2-4611-88f3-4392146e107f", "type": "topic", "title": "Platform Algorithms, AI-Generated Content, and Disclosure Ethics", "description": "The modern digital newsroom operates inside algorithmic distribution and synthetic-media environments. Students learn how platforms and AI affect discovery, evidence, trust, and editorial transparency.", "children": [{"id": "3a7a5601-0863-44b0-b2ae-8633f46571e5", "type": "subtopic", "title": "Platform algorithms and distribution power", "children": [{"id": "48ec162c-d54d-4f06-8047-0df123f43510", "type": "concept", "title": "ranking signals and virality"}, {"id": "d4b79979-0c80-43c3-b87a-8dcf5bf620cb", "type": "concept", "title": "platform dependency"}, {"id": "4a7b9349-ac8e-4c94-a67d-dc7af956b733", "type": "concept", "title": "shadow audiences and filter effects"}], "description": "Students examine how recommendation systems influence attention, audience segmentation, and public knowledge."}, {"id": "d487053a-be76-470f-900f-62073aa39e77", "type": "subtopic", "title": "AI-assisted newsroom work", "children": [{"id": "511539db-ccf3-427a-ae97-c8c6e360795b", "type": "concept", "title": "prompting and review workflows"}, {"id": "2b9a2980-0d43-45fe-b176-0ea52f230d8d", "type": "concept", "title": "hallucination and source checking"}, {"id": "78037796-dac9-4630-97e9-6e1c9b90fb0d", "type": "concept", "title": "human editorial responsibility"}], "description": "Students evaluate where AI can support research, transcription, summarization, translation, ideation, and production without replacing verification or accountability."}, {"id": "8de43f29-f14b-4d17-b291-43e2236d596e", "type": "subtopic", "title": "Synthetic media and disclosure ethics", "children": [{"id": "e36b77bf-c502-4645-bcd3-93cb216bcb24", "type": "concept", "title": "deepfakes and provenance"}, {"id": "3a6ec424-85b6-42b2-aa96-0fb40ffdcf48", "type": "concept", "title": "disclosure language"}, {"id": "a455ea89-072f-45db-b042-fc43afd3816b", "type": "concept", "title": "policy, consent, and public trust"}], "description": "Students learn to detect, label, and responsibly use or report on AI-generated and manipulated media."}]}], "dbBacked": true}$dsmjjson$::jsonb,
